export class LeadRepository {
  async getAll(): Promise<Lead[]> {
    return prisma.lead.findMany({
      orderBy: { createdAt: "desc" },
    });
  }

  async create(data: CreateLeadInput): Promise<Lead> {
    return prisma.lead.create({
      data: {
        projectName: data.projectName,
        name: data.name,
        email: data.email,
        phone: data.phone,
        message: data.message ?? null,
      },
    });
  }
}

export const leadRepository = new LeadRepository();

export class LeadService {
  constructor(private repo = leadRepository) {}

  async createLead(data: CreateLeadInput): Promise<Lead> {
    if (!data.name.trim()) throw new Error("Name is required.");
    if (!data.phone.trim()) throw new Error("Phone number is required.");

    const cleanPhone = data.phone.replace(/\D/g, "");
    if (cleanPhone.length < 10) {
      throw new Error("Please enter a valid 10-digit mobile number.");
    }

    return this.repo.create({
      ...data,
      phone: cleanPhone,
    });
  }
}

export class LeadController {
  constructor(private service = leadService) {}

  async createLead(req: Request): Promise<NextResponse> {
    try {
      const body = await req.json();
      const lead = await this.service.createLead(body);
      return NextResponse.json({ success: true, data: lead }, { status: 201 });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Failed to submit lead";
      return NextResponse.json({ success: false, error: message }, { status: 400 });
    }
  }
}

export async function POST(req: NextRequest) {
  // Controller acts as orchestrator
  return leadController.createLead(req);
}
